var i=231;var a=[{id:`cooking-231-01`,theoryId:231,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which nutrient helps the body absorb non-heme iron from plant foods?`,ua:`Яка поживна речовина допомагає засвоювати негемове залізо з рослинних продуктів?`},explanation:{en:`Vitamin C can improve absorption of non-heme iron when eaten with a meal.`,ua:`Вітамін C може покращувати засвоєння негемового заліза під час того самого прийому їжі.`},options:[{id:`a`,text:{en:`Vitamin C`,ua:`Вітамін C`}},{id:`b`,text:{en:`Table salt alone`,ua:`Лише кухонна сіль`}},{id:`c`,text:{en:`Trans fat`,ua:`Трансжири`}}],answer:{optionIds:[`a`]}},{id:`cooking-231-02`,theoryId:231,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`The amount of a mineral in food always equals the amount the body absorbs.`,ua:`Кількість мінералу в продукті завжди дорівнює кількості, яку засвоює організм.`},explanation:{en:`Bioavailability varies with food matrix, preparation, and dietary interactions.`,ua:`Біодоступність залежить від структури продукту, приготування та харчових взаємодій.`},answer:{value:!1}},{id:`cooking-231-03`,theoryId:231,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match micronutrients and supporting factors.`,ua:`Поєднайте мікронутрієнти й чинники, що допомагають їх засвоювати.`},explanation:{en:`Nutrient interactions matter alongside nutrient quantity.`,ua:`Взаємодії між поживними речовинами важливі поряд із їхньою кількістю.`},leftItems:[{id:`l1`,text:{en:`Vitamin C`,ua:`Вітамін C`}},{id:`l2`,text:{en:`Dietary fat`,ua:`Харчовий жир`}},{id:`l3`,text:{en:`Calcium`,ua:`Кальцій`}}],rightItems:[{id:`r1`,text:{en:`Helps non-heme iron absorption`,ua:`Допомагає засвоювати негемове залізо`}},{id:`r3`,text:{en:`Supports bone and muscle functions`,ua:`Підтримує кістки та роботу м’язів`}},{id:`r2`,text:{en:`Aids absorption of fat-soluble vitamins`,ua:`Сприяє засвоєнню жиророзчинних вітамінів`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-231-04`,theoryId:231,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A lentil salad is a key iron source in a plant-based meal. What addition may improve iron absorption?`,ua:`Салат із сочевиці є основним джерелом заліза в рослинній страві. Що може покращити засвоєння заліза?`},explanation:{en:`Vitamin-C-rich ingredients can improve non-heme iron absorption.`,ua:`Інгредієнти, багаті на вітамін C, можуть покращувати засвоєння негемового заліза.`},options:[{id:`a`,text:{en:`Remove all vegetables`,ua:`Прибрати всі овочі`}},{id:`b`,text:{en:`Only extra refined sugar`,ua:`Лише більше рафінованого цукру`}},{id:`c`,text:{en:`Fresh bell peppers or lemon dressing`,ua:`Свіжий солодкий перець або лимонна заправка`}}],answer:{optionIds:[`c`]}},{id:`cooking-231-05`,theoryId:231,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which factors can change micronutrient bioavailability?`,ua:`Які чинники можуть змінювати біодоступність мікронутрієнтів?`},explanation:{en:`Absorption depends on chemistry and meal context rather than presentation alone.`,ua:`Засвоєння залежить від хімічних властивостей та складу страви, а не лише від подачі.`},options:[{id:`a`,text:{en:`Food preparation`,ua:`Спосіб приготування`}},{id:`b`,text:{en:`Presence of other dietary components`,ua:`Наявність інших компонентів їжі`}},{id:`c`,text:{en:`Chemical form of the nutrient`,ua:`Хімічна форма речовини`}},{id:`d`,text:{en:`The color of the plate alone`,ua:`Лише колір тарілки`}}],answer:{optionIds:[`a`,`b`,`c`]}}];var n={theoryId:231,exercises:a};export{n as default,a as exercises,i as theoryId};